package com.personal.assistant.module.inbox.controller;import com.personal.assistant.common.response.ApiResponse;import com.personal.assistant.common.security.SecurityContextHelper;import com.personal.assistant.module.inbox.dto.*;import com.personal.assistant.module.inbox.entity.InboxItem;import com.personal.assistant.module.inbox.service.InboxService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/inbox")public class InboxController{private final InboxService service;public InboxController(InboxService service){this.service=service;}private Long uid(){return SecurityContextHelper.currentUserId();}@GetMapping public ApiResponse<List<InboxItem>>list(@RequestParam(required=false)String status){return ApiResponse.success(service.list(uid(),status));}@PostMapping public ApiResponse<InboxItem>create(@Valid@RequestBody InboxCreateRequest request){return ApiResponse.success(service.create(uid(),request));}@PatchMapping("/{id}/confirm")public ApiResponse<Void>confirm(@PathVariable Long id,@Valid@RequestBody InboxConfirmRequest request){service.confirm(uid(),id,request);return ApiResponse.success();}@PatchMapping("/{id}/archive")public ApiResponse<Void>archive(@PathVariable Long id){service.archive(uid(),id);return ApiResponse.success();}}
